package estate.svc;

import estate.api.Context;
import estate.api.Service;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

/** Notifier: sends marketing offers queued by the customer service. */
public class Main implements Service {
    private Context ctx;
    private Connection db;

    @Override
    public void start(Context c) throws Exception {
        this.ctx = c;
        this.db = c.db();
        try (Statement s = db.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS sent(id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id VARCHAR(40) NOT NULL, "
                    + "offer_id VARCHAR(40) NOT NULL, ts BIGINT NOT NULL)");
            // This table is additive so older notifier instances can continue to use sent.
            s.execute("CREATE TABLE IF NOT EXISTS offer_day(customer_id VARCHAR(40) NOT NULL, day_key BIGINT NOT NULL, "
                    + "sent_count INT NOT NULL, capped BIGINT NOT NULL, PRIMARY KEY(customer_id, day_key))");
        }
    }

    @Override
    public void onEvent(String topic, Map<String, String> ev) throws Exception {
        if (!"offer.queued".equals(topic)) return;
        long now = ctx.now();
        long day = Math.floorDiv(now, 100);
        boolean originalAutoCommit = db.getAutoCommit();
        try {
            db.setAutoCommit(false);
            try (PreparedStatement init = db.prepareStatement(
                    "INSERT INTO offer_day(customer_id, day_key, sent_count, capped) "
                            + "SELECT ?, ?, 0, 0 WHERE NOT EXISTS "
                            + "(SELECT 1 FROM offer_day WHERE customer_id = ? AND day_key = ?)")) {
                init.setString(1, ev.get("customerId"));
                init.setLong(2, day);
                init.setString(3, ev.get("customerId"));
                init.setLong(4, day);
                init.executeUpdate();
            }

            int sent;
            long capped;
            try (PreparedStatement q = db.prepareStatement(
                    "SELECT sent_count, capped FROM offer_day WHERE customer_id = ? AND day_key = ? FOR UPDATE")) {
                q.setString(1, ev.get("customerId"));
                q.setLong(2, day);
                try (ResultSet rs = q.executeQuery()) {
                    rs.next();
                    sent = rs.getInt(1);
                    capped = rs.getLong(2);
                }
            }

            // Include sends made by an older version before this row existed.
            int existing = countSent(ev.get("customerId"), day);
            sent = existing;
            if (sent < 2) {
                try (PreparedStatement ins = db.prepareStatement("INSERT INTO sent(customer_id, offer_id, ts) VALUES (?,?,?)")) {
                    ins.setString(1, ev.get("customerId"));
                    ins.setString(2, ev.get("offerId"));
                    ins.setLong(3, now);
                    ins.executeUpdate();
                }
                sent++;
            } else {
                capped++;
            }
            try (PreparedStatement update = db.prepareStatement(
                    "UPDATE offer_day SET sent_count = ?, capped = ? WHERE customer_id = ? AND day_key = ?")) {
                update.setInt(1, sent);
                update.setLong(2, capped);
                update.setString(3, ev.get("customerId"));
                update.setLong(4, day);
                update.executeUpdate();
            }
            db.commit();
        } catch (Exception e) {
            try { db.rollback(); } catch (Exception ignored) { }
            throw e;
        } finally {
            db.setAutoCommit(originalAutoCommit);
        }
    }

    private int countSent(String customerId, long day) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT COUNT(*) FROM sent WHERE customer_id = ? AND ts / 100 = ?")) {
            q.setString(1, customerId);
            q.setLong(2, day);
            try (ResultSet rs = q.executeQuery()) { rs.next(); return rs.getInt(1); }
        }
    }

    @Override
    public Map<String, String> handle(String op, Map<String, String> req) throws ServiceException {
        try {
            switch (op) {
                case "health": {
                    try (Statement s = db.createStatement(); ResultSet rs = s.executeQuery("SELECT COUNT(*) FROM sent")) { rs.next(); }
                    return Map.of("status", "UP");
                }
                case "sent": return sent(req);
                default: throw new ServiceException("error", "unknown op " + op);
            }
        } catch (ServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new ServiceException("error", String.valueOf(e.getMessage()));
        }
    }

    /** Messages sent to a customer: count, ticks, and the cumulative number capped. */
    private Map<String, String> sent(Map<String, String> req) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT ts FROM sent WHERE customer_id = ? ORDER BY id")) {
            q.setString(1, req.get("customerId"));
            StringBuilder ticks = new StringBuilder();
            int n = 0;
            try (ResultSet rs = q.executeQuery()) {
                while (rs.next()) { if (n++ > 0) ticks.append(','); ticks.append(rs.getLong(1)); }
            }
            try (PreparedStatement q2 = db.prepareStatement("SELECT COALESCE(SUM(capped), 0) FROM offer_day WHERE customer_id = ?")) {
                q2.setString(1, req.get("customerId"));
                try (ResultSet rs = q2.executeQuery()) {
                    rs.next();
                    return Map.of("count", String.valueOf(n), "ticks", ticks.toString(), "capped", String.valueOf(rs.getLong(1)));
                }
            }
        }
    }
}
